    void concurrentSameKeyAllocateReplaysFirst() throws Exception {
        long s1 = createStaff("CC-I-1", true);
        long s2 = createStaff("CC-I-2", true);
        long e1 = createElevator("CC-IDEM", COMMISSIONED);
